export class ErpInventoryBusinessError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ErpInventoryBusinessError";
  }
}

export class ErpValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ErpValidationError";
  }
}

export class ErpConflictError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ErpConflictError";
  }
}

/** Phone already belongs to a company contact — used by dental create-patient-with-contact. */
export class DentalPhoneConflictError extends Error {
  readonly code = "PHONE_EXISTS" as const;
  readonly contact: { id: number; name: string; phone: string | null; email: string | null };
  readonly isPatient: boolean;

  constructor(
    contact: { id: number; name: string; phone: string | null; email: string | null },
    isPatient: boolean,
  ) {
    super(
      isPatient
        ? "A patient with this phone number already exists"
        : "A contact with this phone number already exists",
    );
    this.name = "DentalPhoneConflictError";
    this.contact = contact;
    this.isPatient = isPatient;
  }
}

const RESTAURANT_ACTIVE_CONTEXT_STATUSES: RestaurantOrderContext["status"][] = [
  "open",
  "submitted",
  "in_preparation",
  "ready",
];

const RESTAURANT_CLOSED_CONTEXT_STATUSES: RestaurantOrderContext["status"][] = [
  "completed",
  "cancelled",
];

function isRestaurantContextClosed(status: RestaurantOrderContext["status"]): boolean {
  return RESTAURANT_CLOSED_CONTEXT_STATUSES.includes(status);
}

const ACTIVE_INVOICE_EXCLUDED_STATUSES: Invoice["status"][] = ["cancelled", "void"];

const RESTAURANT_KITCHEN_TICKET_COMPLETION_STATUSES: RestaurantKitchenTicket["status"][] = [
  "ready",
  "served",
  "cancelled",
];

function isRestaurantOrderContextCompletionReconciliation(
  data: Partial<Omit<InsertRestaurantOrderContext, "companyId">> & { salesOrderId: number },
): boolean {
  const keys = Object.keys(data).filter(
    (key) => key !== "salesOrderId" && key !== "status" && key !== "updatedAt",
  );
  return keys.length === 0 && data.status === "completed";
}

function isRestaurantKitchenTicketCompletionUpdate(
  updates: Partial<InsertRestaurantKitchenTicket>,
): boolean {
  const keys = Object.keys(updates).filter((key) => key !== "updatedAt");
  if (keys.length === 0) return false;
  const allowedKeys = new Set(["status", "readyAt", "servedAt", "notes"]);
  if (!keys.every((key) => allowedKeys.has(key))) return false;
  if (updates.status == null) return false;
  return RESTAURANT_KITCHEN_TICKET_COMPLETION_STATUSES.includes(updates.status);
}

type ErpHttpError = {
  status: number;
  message: string;
};

const ERP_CONSTRAINT_ERRORS: Record<string, ErpHttpError> = {
  unique_company_account_code: { status: 409, message: "Account code already exists for this company" },
  unique_company_currency_code: { status: 409, message: "Currency code already exists for this company" },
  one_base_currency_per_company: { status: 409, message: "Only one base currency is allowed per company" },
  exchange_rate_history_company_pair_effective_unique: {
    status: 409,
    message: "An exchange rate already exists for that currency pair and effective date",
  },
  invoices_active_sales_order_unique: {
    status: 409,
    message: "An active invoice already exists for this sales order",
  },
  unique_company_tax_group_name: { status: 409, message: "Tax group name already exists for this company" },
  unique_tax_group_rule: { status: 409, message: "That tax rule is already assigned to the tax group" },
  fiscal_year_dates_in_order: { status: 400, message: "Fiscal year start date must be before end date" },
};

export function getErpErrorResponse(error: unknown): ErpHttpError | null {
  if (error instanceof ErpValidationError) {
    return { status: 400, message: error.message };
  }
  if (error instanceof ErpConflictError) {
    return { status: 409, message: error.message };
  }
  if (error instanceof ErpInventoryBusinessError) {
    return { status: 400, message: error.message };
  }
  if (!error || typeof error !== "object") {
    return null;
  }

  const pgError = error as { code?: string; constraint?: string; detail?: string };
  if (pgError.constraint && ERP_CONSTRAINT_ERRORS[pgError.constraint]) {
    return ERP_CONSTRAINT_ERRORS[pgError.constraint];
  }
  if (pgError.code === "23505") {
    return { status: 409, message: "A record with the same unique values already exists" };
  }
  if (pgError.code === "23503") {
    return { status: 400, message: "The request references a related record that does not exist or is not accessible" };
  }
  if (pgError.code === "23514") {
    return { status: 400, message: "The request violates a database validation rule" };
  }
  return null;
}

export function assertValidFiscalYearDateRange(startDate: Date, endDate: Date) {
  if (!(startDate instanceof Date) || Number.isNaN(startDate.getTime())) {
    throw new ErpValidationError("Fiscal year start date is invalid");
  }
  if (!(endDate instanceof Date) || Number.isNaN(endDate.getTime())) {
    throw new ErpValidationError("Fiscal year end date is invalid");
  }
  if (startDate >= endDate) {
    throw new ErpValidationError("Fiscal year start date must be before end date");
  }
}


