  /**
   * Extract event ID from Google Calendar event link
   * @param eventLink The event link URL (e.g., https://www.google.com/calendar/event?eid=<eventId>)
   * @returns The extracted event ID or null if not found
   */
  extractEventIdFromLink(eventLink: string): string | null {
    try {
      if (!eventLink || typeof eventLink !== 'string') {
        return null;
      }

      // Handle full Google Calendar URLs: https://www.google.com/calendar/event?eid=<eventId>
      const googleCalendarMatch = eventLink.match(/[?&]eid=([^&]+)/);
      if (googleCalendarMatch && googleCalendarMatch[1]) {
        let eidParam = decodeURIComponent(googleCalendarMatch[1]);
        
        // Try to base64url decode the eid parameter
        // Google Calendar eid parameters are base64url-encoded and contain event ID + calendar ID separated by space
        try {
          // Replace base64url characters: - with +, _ with /
          let base64String = eidParam.replace(/-/g, '+').replace(/_/g, '/');
          
          // Add padding if needed (base64 strings should be multiples of 4)
          const padding = base64String.length % 4;
          if (padding) {
            base64String += '='.repeat(4 - padding);
          }
          
          // Decode from base64
          const decoded = Buffer.from(base64String, 'base64').toString('utf-8');
          
          // Split by space and take the first part (the event ID)
          const parts = decoded.split(' ');
          if (parts.length > 0 && parts[0]) {
            return parts[0];
          }
        } catch (decodeError) {
          // If base64 decoding fails, fall back to returning the eid as-is
          // This maintains backward compatibility
        }
        
        return eidParam;
      }

      // Handle alternative Google Calendar format: https://calendar.google.com/event?eid=<eventId>
      const altGoogleMatch = eventLink.match(/calendar\.google\.com\/event\?eid=([^&]+)/);
      if (altGoogleMatch && altGoogleMatch[1]) {
        let eidParam = decodeURIComponent(altGoogleMatch[1]);
        
        // Try to base64url decode
        try {
          let base64String = eidParam.replace(/-/g, '+').replace(/_/g, '/');
          const padding = base64String.length % 4;
          if (padding) {
            base64String += '='.repeat(4 - padding);
          }
          const decoded = Buffer.from(base64String, 'base64').toString('utf-8');
          const parts = decoded.split(' ');
          if (parts.length > 0 && parts[0]) {
            return parts[0];
          }
        } catch (decodeError) {
          // Fall back to returning the eid as-is
        }
        
        return eidParam;
      }

      // If it's already just an event ID (no URL), return as-is
      if (eventLink.length > 0 && !eventLink.includes('http') && !eventLink.includes('/')) {
        return eventLink;
      }

      return null;
    } catch (error) {
      console.error('Error extracting event ID from link:', error);
      return null;
    }
  }

  /**
   * Check if a time slot conflicts with existing bookings
   * @param userId The user ID
   * @param companyId The company ID
   * @param calendarType The calendar type ('google' or 'zoho')
   * @param startDateTime Start of the time slot
   * @param endDateTime End of the time slot
   * @returns True if there's a conflict, false if the slot is available
   */
  async checkBookingConflict(userId: number, companyId: number, calendarType: string, startDateTime: Date, endDateTime: Date, calendarId: string = 'primary'): Promise<boolean> {
    try {
      const conflictingBookings: CalendarBooking[] = await db
        .select()
        .from(calendarBookings)
        .where(
          and(
            eq(calendarBookings.userId, userId),
            eq(calendarBookings.companyId, companyId),
            eq(calendarBookings.calendarType, calendarType),
            eq(calendarBookings.calendarId, calendarId),
            inArray(calendarBookings.status, ['pending', 'confirmed']),
            lt(calendarBookings.bufferStartDateTime, endDateTime),
            gt(calendarBookings.bufferEndDateTime, startDateTime)
          )
        );

      if (conflictingBookings.length > 0) {
        return true;
      }

      return false;
    } catch (error: any) {
      console.error('Error checking booking conflict:', error.message);
      // Fail-safe: return true (has conflicts) to prevent double bookings
      return true;
    }
  }

  async acquireSlotLock(userId: number, companyId: number, calendarType: string, startUTC: Date, endUTC: Date, holderId: string, ttlSeconds: number): Promise<{ success: boolean; lock?: CalendarSlotLock; error?: string }> {
    if (
      !(startUTC instanceof Date) ||
      !(endUTC instanceof Date) ||
      Number.isNaN(startUTC.getTime()) ||
      Number.isNaN(endUTC.getTime()) ||
      startUTC.getTime() >= endUTC.getTime()
    ) {
      return { success: false, error: 'invalid_slot_range' };
    }

    try {
      const lock = await db.transaction(async (tx: any) => {
        await tx.delete(calendarSlotLocks).where(lt(calendarSlotLocks.expiresAt, new Date()));
        await tx.execute(sql`SELECT pg_advisory_xact_lock(hashtextextended(${`${userId}:${companyId}:${calendarType}`}, 0))`);

        const [inserted] = await tx
          .insert(calendarSlotLocks)
          .values({
            userId,
            companyId,
            calendarType,
            startDateTime: startUTC,
            endDateTime: endUTC,
            lockToken: randomUUID(),
            acquiredBy: holderId,
            expiresAt: new Date(Date.now() + ttlSeconds * 1000)
          })
          .returning();

        return inserted;
      });

      return lock ? { success: true, lock } : { success: false, error: 'lock_conflict' };
    } catch (error: any) {
      if (error.code === '23P01' || error.message?.includes('calendar_slot_locks_no_overlap')) {
        return { success: false, error: 'lock_conflict' };
      }

      console.error('Error acquiring calendar slot lock:', error);
      return { success: false, error: error.message || 'failed_to_acquire_lock' };
    }
  }

