  async pinContact(userId: number, contactId: number, companyId?: number): Promise<{ success: boolean; error?: string }> {
    try {
      const existingCount = await db
        .select({ count: count() })
        .from(userContactPins)
        .where(eq(userContactPins.userId, userId));
      const currentCount = existingCount[0]?.count ?? 0;
      if (currentCount >= 7) {
        return { success: false, error: 'Maximum 7 contacts can be pinned' };
      }
      await db.insert(userContactPins).values({
        userId,
        contactId,
        companyId: companyId ?? null
      }).onConflictDoNothing({ target: [userContactPins.userId, userContactPins.contactId] });
      return { success: true };
    } catch (error) {
      console.error('[Storage] Error pinning contact:', error);
      return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
    }
  }

  async unpinContact(userId: number, contactId: number): Promise<{ success: boolean }> {
    try {
      await db.delete(userContactPins).where(
        and(eq(userContactPins.userId, userId), eq(userContactPins.contactId, contactId))
      );
      return { success: true };
    } catch (error) {
      console.error('[Storage] Error unpinning contact:', error);
      return { success: false };
    }
  }

