  async createConversation(conversation: InsertConversation): Promise<Conversation> {
    const [newConversation] = await db.insert(conversations).values(conversation).returning();
    import('./services/conversation-metrics-service').then(m =>
      m.default.initMetric(
        newConversation.id,
        newConversation.companyId,
        newConversation.channelType,
        newConversation.createdAt ?? new Date()
      ).catch(e => console.error('[metrics] initMetric failed:', e))
    );
    return newConversation;
  }

