  /**
   * Get recent messages for AI Assistant use.
   * Returns the latest N messages in chronological order (oldest first, newest last).
   * Unlike getMessagesByConversationPaginated which returns newest first, this is optimized for AI prompt building.
   */
  async getRecentMessagesForAI(conversationId: number, limit: number): Promise<Message[]> {
    // First get the latest N messages (newest first), then reverse to chronological order
    const recentMessages = await db
      .select()
      .from(messages)
      .where(eq(messages.conversationId, conversationId))
      .orderBy(desc(messages.sentAt), desc(messages.createdAt), desc(messages.id))
      .limit(limit);

    // Reverse to get chronological order (oldest first) for AI prompt building
    return recentMessages.reverse();
  }

