  async getWebhookTriggerLogsByFlowId(
    flowId: number,
    options: { status?: string; limit: number; offset: number; search?: string }
  ): Promise<{ logs: WebhookTriggerLog[]; total: number }> {
    const { status, limit, offset, search } = options;
    const conditions = [eq(webhookTriggerLogs.flowId, flowId)];
    if (status) {
      conditions.push(eq(webhookTriggerLogs.status, status as 'received' | 'filtered' | 'triggered' | 'failed'));
    }
    if (search && search.trim()) {
      conditions.push(sql`${webhookTriggerLogs.payload}::text ILIKE ${'%' + search.trim() + '%'}` as SQL);
    }
    const whereClause = conditions.length === 1 ? conditions[0] : and(...conditions);
    const [totalResult] = await db
      .select({ count: count() })
      .from(webhookTriggerLogs)
      .where(whereClause);
    const total = Number(totalResult?.count ?? 0);
    const logs = await db
      .select()
      .from(webhookTriggerLogs)
      .where(whereClause)
      .orderBy(desc(webhookTriggerLogs.createdAt))
      .limit(limit)
      .offset(offset);
    return { logs, total };
  }

  async getWebhookTriggerLogsCountByFlowId(flowId: number, last24Hours?: boolean): Promise<number> {
    const conditions = [eq(webhookTriggerLogs.flowId, flowId)];
    if (last24Hours) {
      const since = new Date(Date.now() - 24 * 60 * 60 * 1000);
      conditions.push(gte(webhookTriggerLogs.createdAt, since));
    }
    const [result] = await db
      .select({ count: count() })
      .from(webhookTriggerLogs)
      .where(and(...conditions));
    return Number(result?.count ?? 0);
  }

  async deleteWebhookTriggerLogsByFlowId(flowId: number): Promise<number> {
    const deleted = await db
      .delete(webhookTriggerLogs)
      .where(eq(webhookTriggerLogs.flowId, flowId))
      .returning({ id: webhookTriggerLogs.id });
    return deleted.length;
  }

