  async withFlowTriggerDecisionLock<T>(
    companyId: number,
    conversationId: number,
    triggerNodeId: string,
    fn: () => Promise<T>
  ): Promise<T> {
    const lockKey = `flow-trigger-decision:${companyId}:${conversationId}:${triggerNodeId}`;
    return db.transaction(async (tx: any) => {
      await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${lockKey}))`);
      return await fn();
    });
  }

