  async getArchivedContactsCount(options?: { companyId?: number; userId?: number; contactScope?: 'own' | 'assigned' | 'company' }): Promise<number> {
    const whereConditions = this.buildContactsListWhereConditions({
      ...options,
      archivedOnly: true,
    });

    const needsPhoneDedup = await this.scopedContactsHavePhoneDuplicates(whereConditions);

    if (!needsPhoneDedup) {
      const [countRow] = await db
        .select({ count: sql<number>`COUNT(*)::int` })
        .from(contacts)
        .where(whereConditions ?? sql`true`);
      return Number(countRow?.count || 0);
    }

    const { rankedSubquery } = this.buildRankedContactsSubquery(whereConditions);
    const countResult = await db
      .select({ count: sql<number>`COUNT(*)::int` })
      .from(rankedSubquery)
      .where(eq(rankedSubquery._rowNum, 1));

    return Number(countResult[0]?.count || 0);
  }

