  async createFlowExecution(data: {
    runId?: string;
    executionId: string;
    runtimeType?: 'legacy' | 'session';
    sessionId?: string;
    flowId: number;
    conversationId: number;
    contactId: number;
    companyId?: number;
    triggerNodeId: string;
    currentNodeId?: string | null;
    executionPath?: string[];
    status?: string;
    startedAt?: Date;
    lastActivityAt?: Date;
    contextData?: any;
  }): Promise<number> {
    try {
      const [result] = await db.insert(flowExecutions).values({
        runId: data.runId || data.executionId,
        executionId: data.executionId,
        runtimeType: data.runtimeType || 'legacy',
        sessionId: data.sessionId || null,
        flowId: data.flowId,
        conversationId: data.conversationId,
        contactId: data.contactId,
        companyId: data.companyId,
        triggerNodeId: data.triggerNodeId,
        currentNodeId: data.currentNodeId ?? data.triggerNodeId,
        contextData: data.contextData || {},
        status: data.status || 'running',
        executionPath: data.executionPath || [data.triggerNodeId],
        startedAt: data.startedAt || new Date(),
        lastActivityAt: data.lastActivityAt || new Date()
      }).returning({ id: flowExecutions.id });

      
      return result.id;
    } catch (error) {
      console.error('Error creating flow execution:', error);
      throw error;
    }
  }

  async updateFlowExecution(executionId: string, data: {
    status?: string;
    currentNodeId?: string | null;
    executionPath?: string[];
    contextData?: any;
    completedAt?: Date;
    totalDurationMs?: number;
    completionRate?: number;
    errorMessage?: string;
  }, lookupBy: 'executionId' | 'runId' = 'executionId'): Promise<void> {
    try {
      const updateData: any = {
        lastActivityAt: new Date(),
        updatedAt: new Date()
      };

      if (data.status !== undefined) updateData.status = data.status;
      if (data.currentNodeId !== undefined) updateData.currentNodeId = data.currentNodeId;
      if (data.executionPath !== undefined) updateData.executionPath = data.executionPath;
      if (data.contextData !== undefined) updateData.contextData = data.contextData;
      if (data.completedAt !== undefined) updateData.completedAt = data.completedAt;
      if (data.totalDurationMs !== undefined) updateData.totalDurationMs = data.totalDurationMs;
      if (data.completionRate !== undefined) updateData.completionRate = data.completionRate.toString();
      if (data.errorMessage !== undefined) updateData.errorMessage = data.errorMessage;

      await db.update(flowExecutions)
        .set(updateData)
        .where(lookupBy === 'runId'
          ? eq(flowExecutions.runId, executionId)
          : eq(flowExecutions.executionId, executionId));

      
    } catch (error) {
      console.error('Error updating flow execution:', error);
      throw error;
    }
  }

