  async getLatestFlowExecutionContextData(flowId: number): Promise<Record<string, unknown> | null> {
    const rows = await db
      .select({ contextData: flowExecutions.contextData })
      .from(flowExecutions)
      .where(eq(flowExecutions.flowId, flowId))
      .orderBy(desc(flowExecutions.startedAt), desc(flowExecutions.id))
      .limit(25);
    for (const r of rows) {
      const cd = r.contextData;
      if (cd && typeof cd === 'object' && !Array.isArray(cd)) {
        const o = cd as Record<string, unknown>;
        if (Object.keys(o).length > 0) {
          return o;
        }
      }
    }
    return null;
  }

  async getFlowExecutionHistoryDetail(flowId: number, runId: string): Promise<{
    run: {
      id: number;
      runId: string;
      executionId: string;
      runtimeType: 'legacy' | 'session';
      sessionId: string | null;
      flowId: number;
      conversationId: number;
      contactId: number;
      companyId: number | null;
      status: string;
      triggerNodeId: string;
      currentNodeId: string | null;
      executionPath: unknown;
      contextData: unknown;
      startedAt: Date | null;
      lastActivityAt: Date | null;
      completedAt: Date | null;
      totalDurationMs: number | null;
      errorMessage: string | null;
    };
    steps: Array<{
      id: number;
      flowExecutionId: number;
      sessionId: string | null;
      nodeId: string;
      nodeType: string;
      stepOrder: number;
      status: string;
      startedAt: Date | null;
      completedAt: Date | null;
      durationMs: number | null;
      errorMessage: string | null;
      inputData: unknown;
      outputData: unknown;
      retryCount: number | null;
      maxRetries: number | null;
    }>;
  } | undefined> {
    const [run] = await db
      .select({
        id: flowExecutions.id,
        runId: flowExecutions.runId,
        executionId: flowExecutions.executionId,
        runtimeType: flowExecutions.runtimeType,
        sessionId: flowExecutions.sessionId,
        flowId: flowExecutions.flowId,
        conversationId: flowExecutions.conversationId,
        contactId: flowExecutions.contactId,
        companyId: flowExecutions.companyId,
        status: flowExecutions.status,
        triggerNodeId: flowExecutions.triggerNodeId,
        currentNodeId: flowExecutions.currentNodeId,
        executionPath: flowExecutions.executionPath,
        contextData: flowExecutions.contextData,
        startedAt: flowExecutions.startedAt,
        lastActivityAt: flowExecutions.lastActivityAt,
        completedAt: flowExecutions.completedAt,
        totalDurationMs: flowExecutions.totalDurationMs,
        errorMessage: flowExecutions.errorMessage
      })
      .from(flowExecutions)
      .where(and(
        eq(flowExecutions.flowId, flowId),
        eq(flowExecutions.runId, runId)
      ))
      .limit(1);

    if (!run) {
      return undefined;
    }

    const steps = await db
      .select({
        id: flowStepExecutions.id,
        flowExecutionId: flowStepExecutions.flowExecutionId,
        sessionId: flowStepExecutions.sessionId,
        nodeId: flowStepExecutions.nodeId,
        nodeType: flowStepExecutions.nodeType,
        stepOrder: flowStepExecutions.stepOrder,
        status: flowStepExecutions.status,
        startedAt: flowStepExecutions.startedAt,
        completedAt: flowStepExecutions.completedAt,
        durationMs: flowStepExecutions.durationMs,
        errorMessage: flowStepExecutions.errorMessage,
        inputData: flowStepExecutions.inputData,
        outputData: flowStepExecutions.outputData,
        retryCount: flowStepExecutions.retryCount,
        maxRetries: flowStepExecutions.maxRetries
      })
      .from(flowStepExecutions)
      .where(eq(flowStepExecutions.flowExecutionId, run.id))
      .orderBy(asc(flowStepExecutions.stepOrder), asc(flowStepExecutions.startedAt), asc(flowStepExecutions.id));

    return { run, steps };
  }

