  async createFlowStepExecution(data: {
    flowExecutionId: number;
    sessionId?: string;
    nodeId: string;
    nodeType: string;
    stepOrder: number;
    status?: string;
    inputData?: any;
    outputData?: any;
    retryCount?: number;
    maxRetries?: number;
  }): Promise<number> {
    try {
      const [result] = await db.insert(flowStepExecutions).values({
        flowExecutionId: data.flowExecutionId,
        sessionId: data.sessionId || null,
        nodeId: data.nodeId,
        nodeType: data.nodeType,
        stepOrder: data.stepOrder,
        inputData: data.inputData || {},
        outputData: data.outputData,
        retryCount: data.retryCount || 0,
        maxRetries: data.maxRetries || 0,
        status: data.status || 'running',
        startedAt: new Date()
      }).returning({ id: flowStepExecutions.id });

      
      return result.id;
    } catch (error) {
      // Session rows are created best-effort; if the DB session insert failed earlier,
      // step execution inserts referencing session_id can violate FK constraints.
      // In that case, retry without sessionId so tracking remains usable.
      const err = error as any;
      if (err?.code === '23503' && String(err?.constraint || '').includes('flow_step_executions_session_id_fkey')) {
        const [result] = await db.insert(flowStepExecutions).values({
          flowExecutionId: data.flowExecutionId,
          sessionId: null,
          nodeId: data.nodeId,
          nodeType: data.nodeType,
          stepOrder: data.stepOrder,
          inputData: data.inputData || {},
          outputData: data.outputData,
          retryCount: data.retryCount || 0,
          maxRetries: data.maxRetries || 0,
          status: data.status || 'running',
          startedAt: new Date()
        }).returning({ id: flowStepExecutions.id });

        return result.id;
      }

      console.error('Error creating flow step execution:', error);
      throw error;
    }
  }

