  // Email verification token methods
  async createEmailVerificationToken(data: InsertEmailVerificationToken): Promise<EmailVerificationToken> {
    try {
      const [token] = await db
        .insert(emailVerificationTokens)
        .values(data)
        .returning();

      if (!token) {
        throw new Error('Failed to create email verification token');
      }

      return token;
    } catch (error) {
      console.error('Error creating email verification token:', error);
      throw error;
    }
  }

  async getEmailVerificationToken(email: string, token: string): Promise<EmailVerificationToken | undefined> {
    try {
      const [verificationToken] = await db
        .select()
        .from(emailVerificationTokens)
        .where(
          and(
            eq(emailVerificationTokens.email, email),
            eq(emailVerificationTokens.token, token),
            eq(emailVerificationTokens.verified, false),
            gt(emailVerificationTokens.expiresAt, new Date())
          )
        )
        .limit(1);

      return verificationToken;
    } catch (error) {
      console.error('Error getting email verification token:', error);
      return undefined;
    }
  }

  async verifyEmailToken(email: string, token: string): Promise<boolean> {
    try {
      // Atomic UPDATE: only succeeds if the token is still unverified and not expired.
      // This prevents TOCTOU race conditions where concurrent requests could each
      // read verified=false before either write completes.
      const [updated] = await db
        .update(emailVerificationTokens)
        .set({
          verified: true,
          verifiedAt: new Date(),
          updatedAt: new Date()
        })
        .where(
          and(
            eq(emailVerificationTokens.email, email),
            eq(emailVerificationTokens.token, token),
            eq(emailVerificationTokens.verified, false),
            gt(emailVerificationTokens.expiresAt, new Date())
          )
        )
        .returning();

      return !!updated;
    } catch (error) {
      console.error('Error verifying email token:', error);
      return false;
    }
  }

  async invalidatePendingEmailVerificationTokens(email: string): Promise<number> {
    try {
      const result = await db
        .update(emailVerificationTokens)
        .set({ verified: true, updatedAt: new Date() }) // mark as used so they can't be replayed
        .where(
          and(
            eq(emailVerificationTokens.email, email),
            eq(emailVerificationTokens.verified, false),
            gt(emailVerificationTokens.expiresAt, new Date())
          )
        );
      return result.rowCount ?? 0;
    } catch (error) {
      console.error('Error invalidating pending email verification tokens:', error);
      return 0;
    }
  }

  async deleteExpiredEmailVerificationTokens(): Promise<number> {
    try {
      const result = await db
        .delete(emailVerificationTokens)
        .where(lt(emailVerificationTokens.expiresAt, new Date()));

      return result.rowCount ?? 0;
    } catch (error) {
      console.error('Error deleting expired email verification tokens:', error);
      return 0;
    }
  }

  private async getBrandingAppName(): Promise<string> {
    const brandingSetting = await this.getAppSetting('branding');
    const brandingValue = brandingSetting?.value as { appName?: string } | undefined;
    return typeof brandingValue?.appName === 'string' && brandingValue.appName.trim()
      ? brandingValue.appName.trim()
      : 'BotHive';
  }

  private async getDefaultLanguageCode(): Promise<string> {
    const defaultLanguage = await this.getDefaultLanguage();
    return defaultLanguage?.code?.toLowerCase() || 'en';
  }

  private async buildLegacyFrontendWebsiteSettings(): Promise<FrontendWebsiteSettings> {
    const [heroTitle, heroSubtitle, featuresTitle, featuresSubtitle, appName, defaultLocale] =
      await Promise.all([
        this.getAppSetting('landing_hero_title'),
        this.getAppSetting('landing_hero_subtitle'),
        this.getAppSetting('landing_features_title'),
        this.getAppSetting('landing_features_subtitle'),
        this.getBrandingAppName(),
        this.getDefaultLanguageCode(),
      ]);

    return buildFrontendWebsiteSettingsFromLegacyKeys(
      {
        heroTitle: heroTitle?.value,
        heroSubtitle: heroSubtitle?.value,
        featuresTitle: featuresTitle?.value,
        featuresSubtitle: featuresSubtitle?.value,
      },
      { appName, defaultLocale }
    );
  }

  async getFrontendWebsiteSettings(): Promise<FrontendWebsiteSettings> {
    const setting = await this.getAppSetting(FRONTEND_WEBSITE_SETTINGS_KEY);

    const [appName, defaultLocale, mediaLibrary] = await Promise.all([
      this.getBrandingAppName(),
      this.getDefaultLanguageCode(),
      this.getFrontendWebsiteMediaLibrary(),
    ]);

    if (!setting?.value) {
      return this.buildLegacyFrontendWebsiteSettings();
    }

    return normalizeFrontendWebsiteSettings(setting.value, {
      appName,
      defaultLocale,
      updatedAt: setting.updatedAt?.toISOString(),
      mediaLibrary,
    });
  }

  async saveFrontendWebsiteSettings(
    settings: FrontendWebsiteSettingsPayload
  ): Promise<FrontendWebsiteSettings> {
    const [appName, defaultLocale, mediaLibrary] = await Promise.all([
      this.getBrandingAppName(),
      this.getDefaultLanguageCode(),
      this.getFrontendWebsiteMediaLibrary(),
    ]);

    const normalized = normalizeFrontendWebsiteSettings(settings, {
      appName,
      defaultLocale,
      mediaLibrary,
    });
    const parsed = frontendWebsiteSettingsPayloadSchema.parse(normalized);
    const now = new Date().toISOString();
    const payload: FrontendWebsiteSettings = {
      ...parsed,
      updatedAt: now,
    };

    const saved = await this.saveAppSetting(FRONTEND_WEBSITE_SETTINGS_KEY, payload);

    return normalizeFrontendWebsiteSettings(saved.value, {
      appName,
      defaultLocale,
      updatedAt: saved.updatedAt?.toISOString() ?? now,
      mediaLibrary,
    });
  }

  async getFrontendWebsiteMediaLibrary(): Promise<FrontendWebsiteMediaLibrary> {
    const setting = await this.getAppSetting(FRONTEND_WEBSITE_MEDIA_LIBRARY_KEY);

    if (!setting?.value) {
      return normalizeFrontendWebsiteMediaLibrary(undefined);
    }

    return normalizeFrontendWebsiteMediaLibrary(setting.value, {
      updatedAt: setting.updatedAt?.toISOString(),
    });
  }

  async saveFrontendWebsiteMediaLibrary(
    library: FrontendWebsiteMediaLibrary
  ): Promise<FrontendWebsiteMediaLibrary> {
    const normalized = normalizeFrontendWebsiteMediaLibrary(library);
    const saved = await this.saveAppSetting(FRONTEND_WEBSITE_MEDIA_LIBRARY_KEY, normalized);

    return normalizeFrontendWebsiteMediaLibrary(saved.value, {
      updatedAt: saved.updatedAt?.toISOString(),
    });
  }

