  async replaceDealAutomationRules(companyId: number, rules: InsertDealAutomationRule[]): Promise<DealAutomationRule[]> {
    try {
      return await db.transaction(async (tx: any) => {
        // Delete all existing rules for this company
        await tx.delete(dealAutomationRules).where(eq(dealAutomationRules.companyId, companyId));

        if (rules.length === 0) {
          return [];
        }

        // Insert new rules
        const rulesToInsert = rules.map((rule, index) => ({
          ...rule,
          companyId, // Force companyId
          priority: index, // ALWAYS normalize priority based on array order
          enabled: rule.enabled ?? true,
          conditions: rule.conditions ?? { dealStatus: 'active' },
          createdAt: new Date(),
          updatedAt: new Date(),
        }));

        const result = await tx
          .insert(dealAutomationRules)
          .values(rulesToInsert)
          .returning();

        // Return inserted rows ordered by priority
        return result.sort((a: DealAutomationRule, b: DealAutomationRule) => (a.priority - b.priority) || (a.id - b.id));
      });
    } catch (error) {
      console.error(`Error replacing deal automation rules for company ${companyId}:`, error);
      throw error;
    }
  }

