        data.provider === 'tiktok'
          ? (encryptTikTokPartnerConfigurationForWrite(data as Partial<PartnerConfiguration>) as InsertPartnerConfiguration)
          : data;
      const [config] = await db
        .insert(partnerConfigurations)
