  /**
   * Atomically increments each API rate-limit bucket (row-locked via INSERT … ON CONFLICT).
   * Rolls back all increments if any window would exceed its limit.
   */
  async claimApiRateLimitBuckets(
    apiKeyId: number,
    buckets: Array<{ windowType: string; windowStart: Date; limit: number }>
  ): Promise<
    | { ok: true; minuteWindow: ApiRateLimit }
    | { ok: false; windowType: string; limit: number; windowStart: Date }
  > {
    const result = await db.transaction(async (tx: any) => {
      for (const b of buckets) {
        const execResult = await tx.execute(sql`
          INSERT INTO api_rate_limits (api_key_id, window_type, window_start, request_count, updated_at)
          VALUES (${apiKeyId}, ${b.windowType}, ${b.windowStart}, 1, NOW())
          ON CONFLICT (api_key_id, window_type, window_start)
          DO UPDATE SET
            request_count = api_rate_limits.request_count + 1,
            updated_at = NOW()
          WHERE api_rate_limits.request_count < ${b.limit}
          RETURNING id
        `);
        const rows = (execResult as { rows?: { id: number }[] }).rows;
        if (!rows?.length) {
          return {
            ok: false as const,
            windowType: b.windowType,
            limit: b.limit,
            windowStart: b.windowStart
          };
        }
      }
      return { ok: true as const };
    });

    if (!result.ok) {
      return result;
    }

    const minute = buckets.find((x) => x.windowType === 'minute');
    const minuteRow = minute
      ? await this.getRateLimit(apiKeyId, 'minute', minute.windowStart)
      : null;
    if (!minuteRow) {
      return {
        ok: false,
        windowType: 'minute',
        limit: minute?.limit ?? 0,
        windowStart: minute?.windowStart ?? new Date()
      };
    }
    return { ok: true, minuteWindow: minuteRow };
  }

  async createOrUpdateRateLimit(data: InsertApiRateLimit): Promise<ApiRateLimit> {
    try {
      const result = await db.execute(sql`
        INSERT INTO api_rate_limits (api_key_id, window_type, window_start, request_count, updated_at)
        VALUES (${data.apiKeyId}, ${data.windowType}, ${data.windowStart}, 1, NOW())
        ON CONFLICT (api_key_id, window_type, window_start)
        DO UPDATE SET
          request_count = api_rate_limits.request_count + 1,
          updated_at = NOW()
        RETURNING *
      `);
      const row = (result as { rows?: Record<string, unknown>[] }).rows?.[0];
      if (row) {
        return row as unknown as ApiRateLimit;
      }
      const [fallback] = await db
        .select()
        .from(apiRateLimits)
        .where(
          and(
            eq(apiRateLimits.apiKeyId, data.apiKeyId),
            eq(apiRateLimits.windowType, data.windowType),
            eq(apiRateLimits.windowStart, data.windowStart)
          )
        )
        .limit(1);
      if (!fallback) {
        throw new Error('createOrUpdateRateLimit: row missing after upsert');
      }
      return fallback;
    } catch (error) {
      throw error;
    }
  }

  async claimDueScheduledMessages(
    limit: number,
    options?: { leaseMs?: number; claimId?: string }
  ): Promise<ScheduledMessage[]> {
    const leaseMs = options?.leaseMs ?? 15 * 60 * 1000;
    const claimId = options?.claimId ?? `sm-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    return await db.transaction(async (tx: any) => {
      const idResult = await tx.execute(sql`
        WITH cte AS (
          SELECT id FROM scheduled_messages
          WHERE (
            (status IN ('pending', 'scheduled') AND scheduled_for <= NOW())
            OR (status = 'processing' AND processing_lease_expires_at IS NOT NULL AND processing_lease_expires_at < NOW())
          )
          ORDER BY scheduled_for ASC
          FOR UPDATE SKIP LOCKED
          LIMIT ${limit}
        )
        UPDATE scheduled_messages sm
        SET
          status = 'processing',
          attempts = sm.attempts + 1,
          last_attempt_at = NOW(),
          updated_at = NOW(),
          processing_lease_expires_at = NOW() + (${leaseMs} * interval '1 millisecond'),
          processing_claim_id = ${claimId}
        FROM cte
        WHERE sm.id = cte.id
        RETURNING sm.id
      `);
      const ids = ((idResult as { rows?: { id: number }[] }).rows ?? []).map((r) => r.id);
      if (ids.length === 0) {
        return [];
      }
      return await tx
        .select()
        .from(scheduledMessages)
        .where(inArray(scheduledMessages.id, ids))
        .orderBy(asc(scheduledMessages.scheduledFor));
    });
  }

  async claimDueFollowUps(
    limit: number,
    options?: { leaseMs?: number; claimId?: string }
  ): Promise<Record<string, unknown>[]> {
    const leaseMs = options?.leaseMs ?? 15 * 60 * 1000;
    const claimId = options?.claimId ?? `fu-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    return await db.transaction(async (tx: any) => {
      const idResult = await tx.execute(sql`
        WITH cte AS (
          SELECT id FROM follow_up_schedules
          WHERE (
            (status = 'scheduled' AND scheduled_for IS NOT NULL AND scheduled_for <= NOW())
            OR (status = 'processing' AND processing_lease_expires_at IS NOT NULL AND processing_lease_expires_at < NOW())
          )
          ORDER BY scheduled_for ASC NULLS LAST
          FOR UPDATE SKIP LOCKED
          LIMIT ${limit}
        )
        UPDATE follow_up_schedules f
        SET
          status = 'processing',
          updated_at = NOW(),
          dispatch_started_at = NULL,
          processing_lease_expires_at = NOW() + (${leaseMs} * interval '1 millisecond'),
          processing_claim_id = ${claimId}
        FROM cte
        WHERE f.id = cte.id
        RETURNING f.id
      `);
      const ids = ((idResult as { rows?: { id: number }[] }).rows ?? []).map((r) => r.id);
      if (ids.length === 0) {
        return [];
      }
      const rows = await tx
        .select()
        .from(followUpSchedules)
        .where(inArray(followUpSchedules.id, ids))
        .orderBy(asc(followUpSchedules.scheduledFor));
      return rows as Record<string, unknown>[];
    });
  }

