  async getRecentFlowSessions(flowId: number, limit: number = 50, offset: number = 0): Promise<Array<{
    sessionId: string;
    status: string;
    startedAt: Date;
    lastActivityAt: Date;
    completedAt?: Date;
    contactName?: string;
    contactPhone?: string;
    conversationId: number;
    variableCount: number;
  }>> {
    try {

      const sessions = await db
        .select({
          sessionId: flowSessions.sessionId,
          status: flowSessions.status,
          startedAt: flowSessions.startedAt,
          lastActivityAt: flowSessions.lastActivityAt,
          completedAt: flowSessions.completedAt,
          conversationId: flowSessions.conversationId,
          contactName: contacts.name,
          contactPhone: contacts.phone,
          variableCount: sql<number>`COALESCE(var_counts.count, 0)`
        })
        .from(flowSessions)
        .leftJoin(contacts, eq(flowSessions.contactId, contacts.id))
        .leftJoin(
          sql`(
            SELECT session_id, COUNT(*) as count
            FROM flow_session_variables
            GROUP BY session_id
          ) var_counts`,
          sql`var_counts.session_id = ${flowSessions.sessionId}`
        )
        .where(eq(flowSessions.flowId, flowId))
        .orderBy(desc(flowSessions.lastActivityAt))
        .limit(limit)
        .offset(offset);

      return sessions.map((session: any) => ({
        sessionId: session.sessionId,
        status: session.status,
        startedAt: session.startedAt,
        lastActivityAt: session.lastActivityAt,
        completedAt: session.completedAt || undefined,
        contactName: session.contactName || undefined,
        contactPhone: session.contactPhone || undefined,
        conversationId: session.conversationId,
        variableCount: session.variableCount
      }));
    } catch (error) {
      console.error('Error getting recent flow sessions:', error);
      return [];
    }
  }

  async getFlowVariablesPaginated(sessionId: string, options: {
    scope?: 'global' | 'flow' | 'node' | 'user' | 'session';
    limit: number;
    offset: number;
  }): Promise<{
    variables: Array<{
      variableKey: string;
      variableValue: any;
      variableType: string;
      nodeId?: string;
      createdAt: Date;
      updatedAt: Date;
    }>;
    totalCount: number;
  }> {
    try {
      const { scope = 'session', limit, offset } = options;


      const conditions = [eq(flowSessionVariables.sessionId, sessionId)];
      if (scope) {
        conditions.push(eq(flowSessionVariables.scope, scope));
      }


      const [countResult] = await db
        .select({ count: count() })
        .from(flowSessionVariables)
        .where(and(...conditions));

      const totalCount = countResult?.count || 0;


      const variables = await db
        .select({
          variableKey: flowSessionVariables.variableKey,
          variableValue: flowSessionVariables.variableValue,
          variableType: flowSessionVariables.variableType,
          nodeId: flowSessionVariables.nodeId,
          createdAt: flowSessionVariables.createdAt,
          updatedAt: flowSessionVariables.updatedAt
        })
        .from(flowSessionVariables)
        .where(and(...conditions))
        .orderBy(flowSessionVariables.createdAt)
        .limit(limit)
        .offset(offset);

      return {
        variables: variables.map((variable: any) => ({
          ...variable,
          nodeId: variable.nodeId || undefined
        })),
        totalCount
      };
    } catch (error) {
      console.error('Error getting paginated flow variables:', error);
      return {
        variables: [],
        totalCount: 0
      };
    }
  }

  async deleteAllFlowSessions(flowId: number): Promise<number> {
    try {

      const sessions = await db
        .select({ sessionId: flowSessions.sessionId })
        .from(flowSessions)
        .where(eq(flowSessions.flowId, flowId));

      if (sessions.length === 0) {
        return 0;
      }

      const sessionIds = sessions.map((s: any) => s.sessionId);


      await db
        .delete(flowSessionVariables)
        .where(inArray(flowSessionVariables.sessionId, sessionIds));


      const result = await db
        .delete(flowSessions)
        .where(eq(flowSessions.flowId, flowId));

      return sessions.length;
    } catch (error) {
      console.error('Error deleting all flow sessions:', error);
      throw error;
    }
  }

  async getCapturedFormSubmissions(
    companyId: number,
    filters: { flowId?: number; contactId?: number; startDate?: Date; endDate?: Date; page: number; limit: number }
  ): Promise<{
    data: Array<{
      id: number;
      flowId: number;
      flowName: string;
      contactId: number;
      contactName: string;
      nodeId: string;
      sessionId: string | null;
      capturedFields: Record<string, any>;
      submittedAt: Date;
      createdAt: Date;
    }>;
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  }> {
    try {
      const { flowId, contactId, startDate, endDate, page, limit } = filters;
      const conditions = [eq(capturedFormSubmissions.companyId, companyId)];

      if (flowId) {
        conditions.push(eq(capturedFormSubmissions.flowId, flowId));
      }

      if (contactId) {
        conditions.push(eq(capturedFormSubmissions.contactId, contactId));
      }

      if (startDate) {
        conditions.push(gte(capturedFormSubmissions.submittedAt, startDate));
      }

      if (endDate) {
        conditions.push(lte(capturedFormSubmissions.submittedAt, endDate));
      }

      const countQuery = db
        .select({ count: count(capturedFormSubmissions.id) })
        .from(capturedFormSubmissions)
        .innerJoin(flows, and(eq(capturedFormSubmissions.flowId, flows.id), eq(flows.companyId, companyId)))
        .innerJoin(contacts, and(eq(capturedFormSubmissions.contactId, contacts.id), eq(contacts.companyId, companyId)))
        .where(and(...conditions));

      const [countResult] = await countQuery;

      const total = countResult?.count || 0;

      const data = await db
        .select({
          id: capturedFormSubmissions.id,
          flowId: capturedFormSubmissions.flowId,
          flowName: flows.name,
          contactId: capturedFormSubmissions.contactId,
          contactName: contacts.name,
          nodeId: capturedFormSubmissions.nodeId,
          sessionId: capturedFormSubmissions.sessionId,
          capturedFields: capturedFormSubmissions.capturedFields,
          submittedAt: capturedFormSubmissions.submittedAt,
          createdAt: capturedFormSubmissions.createdAt
        })
        .from(capturedFormSubmissions)
        .innerJoin(flows, and(eq(capturedFormSubmissions.flowId, flows.id), eq(flows.companyId, companyId)))
        .innerJoin(contacts, and(eq(capturedFormSubmissions.contactId, contacts.id), eq(contacts.companyId, companyId)))
        .where(and(...conditions))
        .orderBy(desc(capturedFormSubmissions.submittedAt))
        .limit(limit)
        .offset((page - 1) * limit);

      return {
        data,
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit)
      };
    } catch (error) {
      console.error('Error getting captured form submissions:', error);
      throw error;
    }
  }

