  async getProducts(
    companyId: number,
    filters?: { search?: string; status?: string; categoryId?: number; type?: string; isMenuItem?: boolean; lowStock?: boolean; limit?: number; offset?: number }
  ): Promise<{ data: ProductListRow[]; total: number }> {
    try {
      const totalStockExpr = sql`COALESCE((SELECT SUM(sl.quantity) FROM stock_levels sl WHERE sl.product_id = ${products.id} AND sl.company_id = ${companyId}), 0)`;
      const lowStockPredicate = sql`${products.minStock} IS NOT NULL AND ${totalStockExpr} <= ${products.minStock}`;

      const conditions: SQL[] = [eq(products.companyId, companyId)];
      if (filters?.status) {
        conditions.push(eq(products.status, filters.status as (typeof products.$inferSelect)["status"]));
      }
      if (filters?.categoryId != null) {
        conditions.push(eq(products.categoryId, filters.categoryId));
      }
      if (filters?.type) {
        conditions.push(eq(products.type, filters.type as (typeof products.$inferSelect)["type"]));
      }
      if (filters?.isMenuItem !== undefined) {
        conditions.push(eq(products.isMenuItem, filters.isMenuItem));
      }
      if (filters?.lowStock === true) {
        conditions.push(lowStockPredicate);
      }
      if (filters?.search?.trim()) {
        const pat = `%${filters.search.trim()}%`;
        conditions.push(
          sql`(
            ${products.name} ILIKE ${pat}
            OR COALESCE(${products.sku}, '') ILIKE ${pat}
            OR EXISTS (
              SELECT 1
              FROM jsonb_each_text(COALESCE(${products.customFields}, '{}'::jsonb)) AS cf(key, value)
              WHERE cf.value ILIKE ${pat}
            )
            OR EXISTS (
              SELECT 1
              FROM product_variants pv
              WHERE pv.company_id = ${companyId}
                AND pv.product_id = ${products.id}
                AND COALESCE(pv.sku, '') ILIKE ${pat}
            )
          )`
        );
      }
      const whereClause = and(...conditions);

      const [{ count }] = await db
        .select({ count: sql`COUNT(*)` })
        .from(products)
        .where(whereClause);

      const limit = filters?.limit ?? 50;
      const offset = filters?.offset ?? 0;

      const data = await db
        .select({
          ...getTableColumns(products),
          totalStock: sql<string | null>`CAST(${totalStockExpr} AS text)`,
          lowStock: sql<boolean>`CAST((${products.minStock} IS NOT NULL AND ${totalStockExpr} <= ${products.minStock}) AS boolean)`,
        })
        .from(products)
        .where(whereClause)
        .orderBy(desc(products.createdAt))
        .limit(limit)
        .offset(offset);

      return { data, total: Number(count) };
    } catch (error) {
      console.error("Error getting products:", error);
      return { data: [], total: 0 };
    }
  }

