  async createProduct(product: InsertProduct): Promise<Product> {
    if (product.categoryId != null) {
      await assertProductCategoryInCompany(product.categoryId, product.companyId);
    }
    if (product.kitchenStationId != null) {
      const station = await this.getRestaurantKitchenStation(product.kitchenStationId);
      if (!station || station.companyId !== product.companyId) {
        throw new Error("Kitchen station does not belong to this company");
      }
    }
    if (product.brandId != null) {
      const brand = await this.getProductBrand(product.brandId);
      if (!brand || brand.companyId !== product.companyId) throw new Error("Brand does not belong to this company");
    }
    if (product.unitId != null) {
      const unit = await this.getProductUnit(product.unitId);
      if (!unit || unit.companyId !== product.companyId) throw new Error("Unit does not belong to this company");
    }
    const next: InsertProduct = {
      ...product,
      estimatedDurationMinutes: product.type === "service" ? product.estimatedDurationMinutes ?? null : null,
    };
    const [row] = await db.insert(products).values(next).returning();
    if (!row) throw new Error("Failed to create product");
    return row;
  }

  async updateProduct(id: number, updates: Partial<InsertProduct>): Promise<Product> {
    const [existing] = await db.select().from(products).where(eq(products.id, id));
    if (!existing) throw new Error("Product not found");
    const next: Partial<InsertProduct> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    delete (next as { createdBy?: number | null }).createdBy;
    if (next.categoryId !== undefined && next.categoryId !== null) {
      await assertProductCategoryInCompany(next.categoryId, existing.companyId);
    }
    if (next.kitchenStationId !== undefined && next.kitchenStationId !== null) {
      const station = await this.getRestaurantKitchenStation(next.kitchenStationId);
      if (!station || station.companyId !== existing.companyId) {
        throw new Error("Kitchen station does not belong to this company");
      }
    }
    if (next.brandId !== undefined && next.brandId !== null) {
      const brand = await this.getProductBrand(next.brandId);
      if (!brand || brand.companyId !== existing.companyId) throw new Error("Brand does not belong to this company");
    }
    if (next.unitId !== undefined && next.unitId !== null) {
      const unit = await this.getProductUnit(next.unitId);
      if (!unit || unit.companyId !== existing.companyId) throw new Error("Unit does not belong to this company");
    }
    const effectiveType = next.type ?? existing.type;
    if (effectiveType !== "service") {
      next.estimatedDurationMinutes = null;
    }
    const [row] = await db
      .update(products)
      .set({ ...next, updatedAt: new Date() })
      .where(eq(products.id, id))
      .returning();
    if (!row) throw new Error("Product not found");
    return row;
  }

