  private async applyMovementToStockLevelTx(tx: any, movement: StockMovement): Promise<void> {
    if (movement.movementType === "transfer") {
      return;
    }
    const delta = Number(movement.quantity);
    if (!Number.isFinite(delta)) {
      throw new ErpInventoryBusinessError(
        `Invalid stock movement quantity for product ${movement.productId}` +
          (movement.variantId != null ? ` (variant ${movement.variantId})` : "")
      );
    }
    const variantCond =
      movement.variantId != null
        ? eq(stockLevels.variantId, movement.variantId)
        : isNull(stockLevels.variantId);

    const [existing] = await tx
      .select()
      .from(stockLevels)
      .where(
        and(
          eq(stockLevels.companyId, movement.companyId),
          eq(stockLevels.productId, movement.productId),
          eq(stockLevels.warehouseId, movement.warehouseId),
          variantCond
        )
      );

    const currentOnHand = existing ? Number(existing.quantity) : 0;
    const nextOnHand = currentOnHand + delta;
    if (!Number.isFinite(currentOnHand) || !Number.isFinite(nextOnHand)) {
      throw new ErpInventoryBusinessError(
        `Invalid stock level at warehouse for product ${movement.productId}` +
          (movement.variantId != null ? ` (variant ${movement.variantId})` : "")
      );
    }
    if (nextOnHand < 0) {
      throw new ErpInventoryBusinessError(
        `Insufficient stock at warehouse for product ${movement.productId}` +
          (movement.variantId != null ? ` (variant ${movement.variantId})` : "")
      );
    }

    if (existing) {
      await tx
        .update(stockLevels)
        .set({
          quantity: String(nextOnHand),
          updatedAt: new Date(),
        })
        .where(eq(stockLevels.id, existing.id));
    } else {
      await tx.insert(stockLevels).values({
        companyId: movement.companyId,
        productId: movement.productId,
        variantId: movement.variantId ?? null,
        warehouseId: movement.warehouseId,
        quantity: String(nextOnHand),
        reservedQty: "0",
      });
    }
  }

