  async deleteWarehouse(id: number): Promise<boolean> {
    try {
      const [hasStock] = await db
        .select({ id: stockLevels.id })
        .from(stockLevels)
        .where(
          and(
            eq(stockLevels.warehouseId, id),
            or(
              sql`COALESCE(${stockLevels.quantity}::numeric, 0) != 0`,
              sql`COALESCE(${stockLevels.reservedQty}::numeric, 0) != 0`
            )
          )
        )
        .limit(1);
      if (hasStock) {
        throw new Error("Cannot delete warehouse with non-zero stock");
      }
      const result = await db.delete(warehouses).where(eq(warehouses.id, id));
      return (result.rowCount ?? 0) > 0;
    } catch (error) {
      console.error(`Error deleting warehouse ${id}:`, error);
      throw error;
    }
  }

