  async upsertStockLevel(stockLevel: InsertStockLevel): Promise<StockLevel> {
    try {
      const variantId = stockLevel.variantId ?? null;
      await db.execute(sql`
        INSERT INTO stock_levels (
          company_id, product_id, variant_id, warehouse_id,
          quantity, reserved_qty, reorder_point, reorder_qty
        ) VALUES (
          ${stockLevel.companyId},
          ${stockLevel.productId},
          ${variantId},
          ${stockLevel.warehouseId},
          ${stockLevel.quantity},
          ${stockLevel.reservedQty ?? "0"},
          ${stockLevel.reorderPoint ?? null},
          ${stockLevel.reorderQty ?? null}
        )
        ON CONFLICT (product_id, (COALESCE(variant_id, 0)), warehouse_id)
        DO UPDATE SET
          quantity = EXCLUDED.quantity,
          reserved_qty = EXCLUDED.reserved_qty,
          reorder_point = EXCLUDED.reorder_point,
          reorder_qty = EXCLUDED.reorder_qty,
          updated_at = NOW()
      `);
      const row = await this.getStockLevelByProductWarehouse(
        stockLevel.productId,
        stockLevel.variantId ?? null,
        stockLevel.warehouseId
      );
      if (!row) throw new Error("Failed to upsert stock level");
      return row;
    } catch (error) {
      console.error("Error upserting stock level:", error);
      throw error;
    }
  }

