  async recordStockSet(
    companyId: number,
    data: { productId: number; variantId?: number; warehouseId: number; quantity: string; notes?: string; userId?: number }
  ): Promise<StockMovement> {
    const existing = await this.getStockLevelByProductWarehouse(
      data.productId,
      data.variantId ?? null,
      data.warehouseId
    );
    const currentOnHand = existing ? Number(existing.quantity) : 0;
    const targetOnHand = Number(data.quantity);
    if (!Number.isFinite(targetOnHand)) {
      throw new ErpInventoryBusinessError(
        `Invalid stock count quantity for product ${data.productId}` +
          (data.variantId != null ? ` (variant ${data.variantId})` : "")
      );
    }
    const delta = targetOnHand - currentOnHand;
    const countNote = `Stock count set to ${targetOnHand}`;
    const notes = data.notes?.trim() ? `${data.notes.trim()} (${countNote})` : countNote;

    return this.createStockMovement({
      companyId,
      productId: data.productId,
      variantId: data.variantId ?? null,
      warehouseId: data.warehouseId,
      movementType: "count",
      quantity: String(delta),
      referenceType: "import",
      referenceId: null,
      notes,
      userId: data.userId ?? null,
    });
  }

