  async createDeliveryNote(note: InsertDeliveryNote): Promise<DeliveryNote> {
    let deliveryNumber = note.deliveryNumber;
    if (!deliveryNumber?.trim()) {
      const d = new Date();
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, "0");
      const day = String(d.getDate()).padStart(2, "0");
      const r = String(Math.floor(Math.random() * 10000)).padStart(4, "0");
      deliveryNumber = `DN-${y}${m}${day}-${r}`;
    }
    const [row] = await db
      .insert(deliveryNotes)
      .values({ ...note, deliveryNumber })
      .returning();
    if (!row) throw new Error("Failed to create delivery note");
    return row;
  }

  async updateDeliveryNote(id: number, updates: Partial<InsertDeliveryNote>): Promise<DeliveryNote> {
    const [existing] = await db.select().from(deliveryNotes).where(eq(deliveryNotes.id, id));
    if (!existing) throw new Error("Delivery note not found");
    const next: Partial<InsertDeliveryNote> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    delete (next as { salesOrderId?: number }).salesOrderId;
    const [row] = await db
      .update(deliveryNotes)
      .set({ ...next, updatedAt: new Date() })
      .where(eq(deliveryNotes.id, id))
      .returning();
    if (!row) throw new Error("Delivery note not found");
    return row;
  }

