  async getRestaurantTableAvailability(companyId: number): Promise<Array<{
    table: RestaurantTable;
    section: RestaurantSection | null;
    isAvailable: boolean;
    activeContext: Pick<RestaurantOrderContext, "id" | "salesOrderId" | "status" | "serviceType" | "createdAt"> | null;
  }>> {
    const rows = await db
      .select({
        table: restaurantTables,
        section: restaurantSections,
      })
      .from(restaurantTables)
      .leftJoin(
        restaurantSections,
        and(
          eq(restaurantSections.id, restaurantTables.sectionId),
          eq(restaurantSections.companyId, restaurantTables.companyId),
        ),
      )
      .where(eq(restaurantTables.companyId, companyId))
      .orderBy(asc(restaurantTables.sortOrder), asc(restaurantTables.label));

    const tableIds = rows.map((row: { table: RestaurantTable; section: RestaurantSection | null }) => row.table.id);
    const activeContexts = tableIds.length
      ? await db
          .select({
            id: restaurantOrderContexts.id,
            salesOrderId: restaurantOrderContexts.salesOrderId,
            status: restaurantOrderContexts.status,
            serviceType: restaurantOrderContexts.serviceType,
            createdAt: restaurantOrderContexts.createdAt,
            tableId: restaurantOrderContexts.tableId,
            salesOrderStatus: salesOrders.status,
          })
          .from(restaurantOrderContexts)
          .leftJoin(
            salesOrders,
            and(
              eq(salesOrders.id, restaurantOrderContexts.salesOrderId),
              eq(salesOrders.companyId, restaurantOrderContexts.companyId),
            ),
          )
          .where(
            and(
              eq(restaurantOrderContexts.companyId, companyId),
              inArray(restaurantOrderContexts.status, RESTAURANT_ACTIVE_CONTEXT_STATUSES),
              inArray(restaurantOrderContexts.tableId, tableIds),
            ),
          )
          .orderBy(desc(restaurantOrderContexts.createdAt))
      : [];

    const activeByTable = new Map<number, (typeof activeContexts)[number]>();
    for (const context of activeContexts) {
      if (context.tableId == null) continue;
      if (context.salesOrderStatus === "cancelled") continue;
      if (activeByTable.has(context.tableId)) continue;
      activeByTable.set(context.tableId, context);
    }

    return rows.map((row: { table: RestaurantTable; section: RestaurantSection | null }) => {
      const activeContext = activeByTable.get(row.table.id) ?? null;
      return {
        table: row.table,
        section: row.section ?? null,
        isAvailable:
          row.table.isActive !== false &&
          (row.section == null || row.section.isActive !== false) &&
          !activeContext,
        activeContext: activeContext
          ? {
              id: activeContext.id,
              salesOrderId: activeContext.salesOrderId,
              status: activeContext.status,
              serviceType: activeContext.serviceType,
              createdAt: activeContext.createdAt,
            }
          : null,
      };
    });
  }

