  async createOrReplaceRestaurantTableQrToken(companyId: number, tableId: number, data: Omit<InsertRestaurantTableQrToken, "companyId" | "tableId">): Promise<RestaurantTableQrToken> {
    return await db.transaction(async (tx: any) => {
      const [table] = await tx.select().from(restaurantTables).where(and(eq(restaurantTables.id, tableId), eq(restaurantTables.companyId, companyId)));
      if (!table) throw new ErpValidationError("Restaurant table does not belong to this company");
      await tx.delete(restaurantTableQrTokens).where(and(eq(restaurantTableQrTokens.companyId, companyId), eq(restaurantTableQrTokens.tableId, tableId)));
      const [row] = await tx.insert(restaurantTableQrTokens).values({ companyId, tableId, ...data }).returning();
      if (!row) throw new Error("Failed to create QR token");
      return row;
    });
  }

