  async getRestaurantReservations(companyId: number, filters?: { status?: string; tableId?: number; dateFrom?: Date; dateTo?: Date; search?: string; limit?: number; offset?: number }): Promise<{ data: RestaurantReservation[]; total: number }> {
    const conditions: SQL[] = [eq(restaurantReservations.companyId, companyId)];
    if (filters?.status) conditions.push(eq(restaurantReservations.status, filters.status as RestaurantReservation["status"]));
    if (filters?.tableId != null) conditions.push(eq(restaurantReservations.tableId, filters.tableId));
    if (filters?.dateFrom) conditions.push(gte(restaurantReservations.reservationAt, filters.dateFrom));
    if (filters?.dateTo) conditions.push(lte(restaurantReservations.reservationAt, filters.dateTo));
    if (filters?.search?.trim()) {
      const pat = `%${filters.search.trim()}%`;
      conditions.push(or(ilike(restaurantReservations.guestName, pat), ilike(restaurantReservations.guestPhone, pat), ilike(restaurantReservations.guestEmail, pat))!);
    }
    const whereClause = and(...conditions);
    const [{ count: totalCount }] = await db.select({ count: sql`COUNT(*)` }).from(restaurantReservations).where(whereClause);
    const limit = filters?.limit ?? 50;
    const offset = filters?.offset ?? 0;
    const data = await db.select().from(restaurantReservations).where(whereClause).orderBy(desc(restaurantReservations.reservationAt)).limit(limit).offset(offset);
    return { data, total: Number(totalCount) };
  }

