  async generatePurchaseOrderNumber(companyId: number): Promise<string> {
    const d = new Date();
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    const prefix = `PO-${y}${m}${day}-`;
    const [{ c }] = await db
      .select({ c: sql<number>`COUNT(*)::int` })
      .from(purchaseOrders)
      .where(and(eq(purchaseOrders.companyId, companyId), ilike(purchaseOrders.orderNumber, `${prefix}%`)));
    const seq = Number(c) + 1;
    return `${prefix}${String(seq).padStart(4, "0")}`;
  }

  async generateGoodsReceiptNumber(companyId: number): Promise<string> {
    const d = new Date();
    const y = d.getFullYear();
    const mo = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    const prefix = `GR-${y}${mo}${day}-`;
    const [{ c }] = await db
      .select({ c: sql<number>`COUNT(*)::int` })
      .from(goodsReceipts)
      .where(and(eq(goodsReceipts.companyId, companyId), ilike(goodsReceipts.receiptNumber, `${prefix}%`)));
    const seq = Number(c) + 1;
    return `${prefix}${String(seq).padStart(4, "0")}`;
  }

  async getPurchaseOrders(
    companyId: number,
    filters?: {
      supplierId?: number;
      status?: string;
      search?: string;
      dateFrom?: Date;
      dateTo?: Date;
      limit?: number;
      offset?: number;
    }
  ): Promise<{ data: PurchaseOrder[]; total: number }> {
    try {
      const conditions: SQL[] = [eq(purchaseOrders.companyId, companyId)];
      if (filters?.status) {
        conditions.push(eq(purchaseOrders.status, filters.status as PurchaseOrder["status"]));
      }
      if (filters?.supplierId != null) {
        conditions.push(eq(purchaseOrders.supplierId, filters.supplierId));
      }
      if (filters?.dateFrom) {
        conditions.push(gte(purchaseOrders.createdAt, filters.dateFrom));
      }
      if (filters?.dateTo) {
        conditions.push(lte(purchaseOrders.createdAt, filters.dateTo));
      }
      if (filters?.search?.trim()) {
        const pat = `%${filters.search.trim()}%`;
        conditions.push(
          or(ilike(purchaseOrders.orderNumber, pat), ilike(suppliers.name, pat))!
        );
      }
      const whereClause = and(...conditions);

      const [{ count: totalCount }] = await db
        .select({ count: sql`COUNT(DISTINCT ${purchaseOrders.id})` })
        .from(purchaseOrders)
        .leftJoin(suppliers, eq(purchaseOrders.supplierId, suppliers.id))
        .where(whereClause);

      const limit = filters?.limit ?? 50;
      const offset = filters?.offset ?? 0;

      const rows = await db
        .select({ order: purchaseOrders })
        .from(purchaseOrders)
        .leftJoin(suppliers, eq(purchaseOrders.supplierId, suppliers.id))
        .where(whereClause)
        .orderBy(desc(purchaseOrders.createdAt))
        .limit(limit)
        .offset(offset);

      return {
        data: rows.map((r: { order: PurchaseOrder }) => r.order),
        total: Number(totalCount),
      };
    } catch (error) {
      console.error("Error getting purchase orders:", error);
      return { data: [], total: 0 };
    }
  }

