  async createPurchaseOrder(order: InsertPurchaseOrder): Promise<PurchaseOrder> {
    const orderNumber =
      order.orderNumber?.trim() || (await this.generatePurchaseOrderNumber(order.companyId));
    const [row] = await db
      .insert(purchaseOrders)
      .values({ ...order, orderNumber })
      .returning();
    if (!row) throw new Error("Failed to create purchase order");
    return row;
  }

  async updatePurchaseOrder(id: number, updates: Partial<InsertPurchaseOrder>): Promise<PurchaseOrder> {
    const [existing] = await db.select().from(purchaseOrders).where(eq(purchaseOrders.id, id));
    if (!existing) throw new Error("Purchase order not found");
    if (updates.status === "cancelled" && existing.status !== "cancelled") {
      const items = await db
        .select({ receivedQty: purchaseOrderItems.receivedQty })
        .from(purchaseOrderItems)
        .where(eq(purchaseOrderItems.purchaseOrderId, id));
      const hasReceivedQty = items.some((item: { receivedQty: unknown }) => Number(item.receivedQty) > 0);
      if (hasReceivedQty) {
        throw new Error("Purchase orders with received quantities cannot be cancelled");
      }
    }
    const next: Partial<InsertPurchaseOrder> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    delete (next as { orderNumber?: string }).orderNumber;
    const [row] = await db
      .update(purchaseOrders)
      .set({ ...next, updatedAt: new Date() })
      .where(eq(purchaseOrders.id, id))
      .returning();
    if (!row) throw new Error("Purchase order not found");
    return row;
  }

  async deletePurchaseOrder(id: number): Promise<boolean> {
    const [existing] = await db.select().from(purchaseOrders).where(eq(purchaseOrders.id, id));
    if (!existing) return false;
    if (existing.status !== "draft") {
      throw new Error("Only draft purchase orders can be deleted");
    }
    const result = await db.delete(purchaseOrders).where(eq(purchaseOrders.id, id));
    return (result.rowCount ?? 0) > 0;
  }

  async getPurchaseOrderItems(purchaseOrderId: number): Promise<PurchaseOrderItem[]> {
    return db
      .select()
      .from(purchaseOrderItems)
      .where(eq(purchaseOrderItems.purchaseOrderId, purchaseOrderId))
      .orderBy(asc(purchaseOrderItems.sortOrder), asc(purchaseOrderItems.id));
  }

  async createPurchaseOrderItem(item: InsertPurchaseOrderItem): Promise<PurchaseOrderItem> {
    const [row] = await db.insert(purchaseOrderItems).values(item).returning();
    if (!row) throw new Error("Failed to create purchase order line item");
    await this.recalculatePurchaseOrderTotals(item.purchaseOrderId);
    const [updatedRow] = await db
      .select()
      .from(purchaseOrderItems)
      .where(eq(purchaseOrderItems.id, row.id));
    if (!updatedRow) throw new Error("Line item not found after recalc");
    return updatedRow;
  }

  async updatePurchaseOrderItem(id: number, updates: Partial<InsertPurchaseOrderItem>): Promise<PurchaseOrderItem> {
    const [existing] = await db.select().from(purchaseOrderItems).where(eq(purchaseOrderItems.id, id));
    if (!existing) throw new Error("Line item not found");
    const next: Partial<InsertPurchaseOrderItem> = { ...updates };
    delete (next as { purchaseOrderId?: number }).purchaseOrderId;
    delete (next as { receivedQty?: unknown }).receivedQty;
    const [row] = await db
      .update(purchaseOrderItems)
      .set(next)
      .where(eq(purchaseOrderItems.id, id))
      .returning();
    if (!row) throw new Error("Line item not found");
    await this.recalculatePurchaseOrderTotals(existing.purchaseOrderId);
    return row;
  }

  async deletePurchaseOrderItem(id: number): Promise<boolean> {
    const [existing] = await db.select().from(purchaseOrderItems).where(eq(purchaseOrderItems.id, id));
    if (!existing) return false;
    const poId = existing.purchaseOrderId;
    await db.delete(purchaseOrderItems).where(eq(purchaseOrderItems.id, id));
    await this.recalculatePurchaseOrderTotals(poId);
    return true;
  }

  async recalculatePurchaseOrderTotals(purchaseOrderId: number): Promise<PurchaseOrder> {
    const items = await this.getPurchaseOrderItems(purchaseOrderId);
    let subtotal = 0;
    for (const item of items) {
      subtotal += Number(item.lineTotal);
    }
    const [order] = await db.select().from(purchaseOrders).where(eq(purchaseOrders.id, purchaseOrderId));
    if (!order) throw new Error("Purchase order not found");
    const taxAmt = Number(order.taxAmount ?? 0);
    const totalAmount = subtotal + taxAmt;
    const [updated] = await db
      .update(purchaseOrders)
      .set({
        subtotal: subtotal.toFixed(2),
        totalAmount: totalAmount.toFixed(2),
        updatedAt: new Date(),
      })
      .where(eq(purchaseOrders.id, purchaseOrderId))
      .returning();
    if (!updated) throw new Error("Purchase order not found");
    return updated;
  }

