  async deleteInvoice(id: number): Promise<boolean> {
    const [existing] = await db.select().from(invoices).where(eq(invoices.id, id));
    if (!existing) return false;
    if (existing.status !== "draft") {
      throw new Error("Only draft invoices can be deleted");
    }
    const [linked] = await db.select({ count: sql<number>`count(*)::int` }).from(invoices).where(eq(invoices.parentInvoiceId, id));
    if (linked && linked.count > 0) {
      throw new Error("Cannot delete invoice because it has linked credit or debit notes");
    }
    const result = await db.delete(invoices).where(eq(invoices.id, id));
    return (result.rowCount ?? 0) > 0;
  }

