  async createInvoiceItem(item: InsertInvoiceItem): Promise<InvoiceItem> {
    const [row] = await db
      .insert(invoiceItems)
      .values({
        ...item,
        lineTotal: this.computeInvoiceLineTotalValue(item, {
          discountValueExplicit: Object.prototype.hasOwnProperty.call(item, 'discountValue'),
        }),
      })
      .returning();
    if (!row) throw new Error("Failed to create invoice line item");
    await this.recalculateInvoiceTotals(item.invoiceId);
    const [updatedRow] = await db.select().from(invoiceItems).where(eq(invoiceItems.id, row.id));
    if (!updatedRow) throw new Error("Line item not found after recalc");
    return updatedRow;
  }

  async updateInvoiceItem(id: number, updates: Partial<InsertInvoiceItem>): Promise<InvoiceItem> {
    const [existing] = await db.select().from(invoiceItems).where(eq(invoiceItems.id, id));
    if (!existing) throw new Error("Line item not found");
    const next: Partial<InsertInvoiceItem> = { ...updates };
    delete (next as { invoiceId?: number }).invoiceId;

    const mergedQty = next.quantity ?? existing.quantity;
    const mergedPrice = next.unitPrice ?? existing.unitPrice;
    const mergedType = next.discountType ?? existing.discountType;
    const mergedPercent = next.discountPercent ?? existing.discountPercent;
    const discountValueExplicit = Object.prototype.hasOwnProperty.call(updates, "discountValue");

    next.lineTotal = this.computeInvoiceLineTotalValue(
      {
        quantity: mergedQty,
        unitPrice: mergedPrice,
        discountType: mergedType,
        discountValue: discountValueExplicit ? next.discountValue : undefined,
        discountPercent: mergedPercent,
      },
      { discountValueExplicit }
    );

    if (
      Object.prototype.hasOwnProperty.call(updates, "discountValue") ||
      Object.prototype.hasOwnProperty.call(updates, "discountType")
    ) {
      const mergedTypeStr = String(next.discountType ?? existing.discountType ?? "percentage");
      if (mergedTypeStr === "fixed_amount") {
        next.discountPercent = "0";
      } else if (discountValueExplicit) {
        next.discountPercent = String(Number(next.discountValue ?? 0));
      }
    }

    const [row] = await db
      .update(invoiceItems)
      .set(next)
      .where(eq(invoiceItems.id, id))
      .returning();
    if (!row) throw new Error("Line item not found");
    await this.recalculateInvoiceTotals(existing.invoiceId);
    return row;
  }

  async deleteInvoiceItem(id: number): Promise<boolean> {
    const [existing] = await db.select().from(invoiceItems).where(eq(invoiceItems.id, id));
    if (!existing) return false;
    const invId = existing.invoiceId;
    await db.delete(invoiceItems).where(eq(invoiceItems.id, id));
    await this.recalculateInvoiceTotals(invId);
    return true;
  }

