  async recordInvoicePayment(payment: InsertInvoicePayment): Promise<InvoicePayment> {
    const amount = Number(payment.amount);
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new Error("Payment amount must be positive");
    }

    await this.seedDefaultChartOfAccounts(payment.companyId);

    const { inserted } = await db.transaction(async (tx: any) => {
      const [invoice] = await tx
        .select()
        .from(invoices)
        .where(and(eq(invoices.id, payment.invoiceId), eq(invoices.companyId, payment.companyId)))
        .limit(1);
      if (!invoice) throw new Error("Invoice not found");

      this.assertInvoiceWorkflowSupported(invoice.type, "payment");
      if (!["sent", "partially_paid", "overdue"].includes(invoice.status)) {
        throw new Error("Invoice must be in sent, partially_paid, or overdue status to record payments");
      }

      const remainingBalance = Number(invoice.amountDue ?? 0);
      if (amount - remainingBalance > 0.0001) {
        throw new Error("Payment amount cannot exceed remaining balance");
      }

      const [insertedPayment] = await tx.insert(invoicePayments).values(payment).returning();
      if (!insertedPayment) throw new Error("Failed to record payment");

      const paid = Number(invoice.amountPaid ?? 0) + amount;
      const total = Number(invoice.totalAmount);
      const due = Math.max(0, total - paid);
      const nextStatus = this.determineInvoicePaymentStatus(invoice, paid, due);
      const [updatedInvoice] = await tx
        .update(invoices)
        .set({
          amountPaid: paid.toFixed(2),
          amountDue: due.toFixed(2),
          status: nextStatus,
          updatedAt: new Date(),
        })
        .where(eq(invoices.id, payment.invoiceId))
        .returning();
      if (!updatedInvoice) throw new Error("Invoice not found");

      if (invoice.type === "sales_invoice") {
        const [ar] = await tx
          .select()
          .from(accountsReceivable)
          .where(and(eq(accountsReceivable.companyId, payment.companyId), eq(accountsReceivable.invoiceId, payment.invoiceId)))
          .limit(1);
        if (!ar) {
          throw new Error("Accounts receivable record not found for invoice");
        }
        const arPaid = Number(ar.paidAmount) + amount;
        const arStatus: ArApStatus = arPaid >= Number(ar.amount) ? "paid" : "partially_paid";
        await this.upsertAccountReceivableWithTx(tx, {
          ...ar,
          paidAmount: arPaid.toFixed(2),
          status: arStatus,
        });
      } else {
        const [ap] = await tx
          .select()
          .from(accountsPayable)
          .where(and(eq(accountsPayable.companyId, payment.companyId), eq(accountsPayable.invoiceId, payment.invoiceId)))
          .limit(1);
        if (!ap) {
          throw new Error("Accounts payable record not found for invoice");
        }
        const apPaid = Number(ap.paidAmount) + amount;
        const apStatus: ArApStatus = apPaid >= Number(ap.amount) ? "paid" : "partially_paid";
        await this.upsertAccountPayableWithTx(tx, {
          ...ap,
          paidAmount: apPaid.toFixed(2),
          status: apStatus,
        });
      }

      await this.createInvoicePaymentJournalEntryWithTx(tx, insertedPayment, updatedInvoice, payment.companyId, payment.recordedBy ?? null);
      return { inserted: insertedPayment };
    });

    await this.emitErpDomainEvent({
      eventKey: `erp.payment.recorded:${inserted.id}`,
      eventType: "erp.payment.recorded",
      companyId: inserted.companyId,
      referenceType: "invoice_payment",
      referenceId: inserted.id,
      actorUserId: inserted.recordedBy ?? null,
      data: { invoiceId: inserted.invoiceId, amount: inserted.amount, paymentDate: inserted.paymentDate?.toISOString?.() ?? null },
    });
    return inserted;
  }

  async updateInvoicePayment(
    id: number,
    companyId: number,
    updates: Partial<InsertInvoicePayment>
  ): Promise<InvoicePayment> {
    const { updatedPayment } = await db.transaction(async (tx: any) => {
      const [existingPayment] = await tx
        .select()
        .from(invoicePayments)
        .where(eq(invoicePayments.id, id))
        .limit(1);
      if (!existingPayment) throw new Error("Payment not found");

      const [invoice] = await tx
        .select()
        .from(invoices)
        .where(and(eq(invoices.id, existingPayment.invoiceId), eq(invoices.companyId, companyId)))
        .limit(1);
      if (!invoice) throw new Error("Invoice not found");

      const nextAmount = updates.amount !== undefined ? Number(updates.amount) : Number(existingPayment.amount);
      if (!Number.isFinite(nextAmount) || nextAmount <= 0) {
        throw new Error("Payment amount must be positive");
      }

      const patch: Partial<InsertInvoicePayment> = { ...updates, amount: nextAmount.toFixed(2) };
      delete (patch as { invoiceId?: number }).invoiceId;
      delete (patch as { companyId?: number }).companyId;

      const [updatedPayment] = await tx
        .update(invoicePayments)
        .set(patch)
        .where(eq(invoicePayments.id, id))
        .returning();
      if (!updatedPayment) throw new Error("Payment not found");

      const allPayments = await tx
        .select()
        .from(invoicePayments)
        .where(eq(invoicePayments.invoiceId, invoice.id));
      const paid = allPayments.reduce((sum: number, p: { amount: string }) => sum + Number(p.amount || 0), 0);
      const total = Number(invoice.totalAmount);
      const due = Math.max(0, total - paid);
      const nextStatus = this.determineInvoicePaymentStatus(invoice, paid, due);

      await tx
        .update(invoices)
        .set({
          amountPaid: paid.toFixed(2),
          amountDue: due.toFixed(2),
          status: nextStatus,
          updatedAt: new Date(),
        })
        .where(eq(invoices.id, invoice.id));

      if (invoice.type === "sales_invoice") {
        const [ar] = await tx
          .select()
          .from(accountsReceivable)
          .where(and(eq(accountsReceivable.companyId, companyId), eq(accountsReceivable.invoiceId, invoice.id)))
          .limit(1);
        if (!ar) throw new Error("Accounts receivable record not found for invoice");
        const arStatus: ArApStatus = paid >= Number(ar.amount) ? "paid" : paid > 0 ? "partially_paid" : "open";
        await this.upsertAccountReceivableWithTx(tx, {
          ...ar,
          paidAmount: paid.toFixed(2),
          status: arStatus,
        });
      } else {
        const [ap] = await tx
          .select()
          .from(accountsPayable)
          .where(and(eq(accountsPayable.companyId, companyId), eq(accountsPayable.invoiceId, invoice.id)))
          .limit(1);
        if (!ap) throw new Error("Accounts payable record not found for invoice");
        const apStatus: ArApStatus = paid >= Number(ap.amount) ? "paid" : paid > 0 ? "partially_paid" : "open";
        await this.upsertAccountPayableWithTx(tx, {
          ...ap,
          paidAmount: paid.toFixed(2),
          status: apStatus,
        });
      }

      return { updatedPayment };
    });

    return updatedPayment;
  }

