  async getUsersByIds(ids: number[]): Promise<Map<number, User>> {
    const uniqueIds = Array.from(new Set(ids.filter((id) => Number.isInteger(id))));
    if (uniqueIds.length === 0) return new Map();
    const rows: User[] = await db.select().from(users).where(inArray(users.id, uniqueIds));
    return new Map(rows.map((row: User) => [row.id, row]));
  }

  async getEmployeeEnrichment(
    employeeIds: number[]
  ): Promise<Map<number, { employee: Employee; user?: User; department?: Department }>> {
    const uniqueIds = Array.from(new Set(employeeIds.filter((id) => Number.isInteger(id))));
    if (uniqueIds.length === 0) return new Map();
    const employeeRows: Employee[] = await db.select().from(employees).where(inArray(employees.id, uniqueIds));
    const userMap = await this.getUsersByIds(employeeRows.map((employee: Employee) => employee.userId));
    const departmentIds = employeeRows
      .map((employee: Employee) => employee.departmentId)
      .filter((id): id is number => id != null);
    const uniqueDepartmentIds = Array.from(new Set(departmentIds));
    const departmentRows: Department[] =
      uniqueDepartmentIds.length > 0
        ? await db.select().from(departments).where(inArray(departments.id, uniqueDepartmentIds))
        : [];
    const departmentMap = new Map(departmentRows.map((department: Department) => [department.id, department]));
    return new Map(
      employeeRows.map((employee: Employee) => [
        employee.id,
        {
          employee,
          user: userMap.get(employee.userId),
          department: employee.departmentId != null ? departmentMap.get(employee.departmentId) : undefined,
        },
      ])
    );
  }

  async createEmployee(employee: InsertEmployee): Promise<Employee> {
    if (employee.managerId != null) {
      await this.assertEmployeeManagerScoped(employee.companyId, employee.managerId);
    }
    const employeeId =
      employee.employeeId?.trim() || (await this.generateEmployeeId(employee.companyId));
    const [row] = await db.insert(employees).values({ ...employee, employeeId }).returning();
    if (!row) throw new Error("Failed to create employee");
    return row;
  }

  async updateEmployee(id: number, updates: Partial<InsertEmployee>): Promise<Employee> {
    const [existing] = await db.select().from(employees).where(eq(employees.id, id));
    if (!existing) throw new Error("Employee not found");
    if (updates.managerId !== undefined && updates.managerId != null) {
      await this.assertEmployeeManagerScoped(existing.companyId, updates.managerId, id);
    }
    const next: Partial<InsertEmployee> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    delete (next as { userId?: number }).userId;
    const [row] = await db
      .update(employees)
      .set({ ...next, updatedAt: new Date() })
      .where(eq(employees.id, id))
      .returning();
    if (!row) throw new Error("Employee not found");
    return row;
  }

  async deleteEmployee(id: number): Promise<boolean> {
    const [row] = await db
      .update(employees)
      .set({ status: "terminated", terminationDate: new Date(), updatedAt: new Date() })
      .where(eq(employees.id, id))
      .returning();
    return !!row;
  }

  async getLeaveRequests(
    companyId: number,
    filters?: {
      employeeId?: number;
      status?: string;
      leaveType?: string;
      dateFrom?: Date;
      dateTo?: Date;
      limit?: number;
      offset?: number;
    }
  ): Promise<{ data: LeaveRequest[]; total: number }> {
    const conditions: SQL[] = [eq(leaveRequests.companyId, companyId)];
    if (filters?.employeeId != null) {
      conditions.push(eq(leaveRequests.employeeId, filters.employeeId));
    }
    if (filters?.status) {
      conditions.push(eq(leaveRequests.status, filters.status as LeaveRequest["status"]));
    }
    if (filters?.leaveType) {
      conditions.push(eq(leaveRequests.leaveType, filters.leaveType as LeaveRequest["leaveType"]));
    }
    if (filters?.dateFrom) {
      conditions.push(gte(leaveRequests.startDate, filters.dateFrom));
    }
    if (filters?.dateTo) {
      conditions.push(lte(leaveRequests.endDate, filters.dateTo));
    }
    const whereClause = and(...conditions);
    const [{ count: totalCount }] = await db
      .select({ count: sql`COUNT(*)` })
      .from(leaveRequests)
      .where(whereClause);
    const limit = filters?.limit ?? 50;
    const offset = filters?.offset ?? 0;
    const data = await db
      .select()
      .from(leaveRequests)
      .where(whereClause)
      .orderBy(desc(leaveRequests.createdAt))
      .limit(limit)
      .offset(offset);
    return { data, total: Number(totalCount) };
  }

  async getLeaveRequest(id: number): Promise<LeaveRequest | undefined> {
    const [row] = await db.select().from(leaveRequests).where(eq(leaveRequests.id, id));
    return row;
  }

  async createLeaveRequest(req: InsertLeaveRequest): Promise<LeaveRequest> {
    if (new Date(req.startDate).getTime() > new Date(req.endDate).getTime()) {
      throw new Error("Leave start date must be on or before end date");
    }
    const days = Number(req.days);
    if (!Number.isFinite(days) || days <= 0) {
      throw new Error("Leave days must be positive");
    }
    const [row] = await db.insert(leaveRequests).values(req).returning();
    if (!row) throw new Error("Failed to create leave request");
    return row;
  }

  async updateLeaveRequest(id: number, updates: Partial<InsertLeaveRequest>): Promise<LeaveRequest> {
    const [existing] = await db.select().from(leaveRequests).where(eq(leaveRequests.id, id));
    if (!existing) throw new Error("Leave request not found");
    const next: Partial<InsertLeaveRequest> = { ...updates };
    delete (next as { companyId?: number }).companyId;
    delete (next as { status?: string }).status;
    delete (next as { approvedBy?: number | null }).approvedBy;
    const startDate = next.startDate !== undefined ? next.startDate : existing.startDate;
    const endDate = next.endDate !== undefined ? next.endDate : existing.endDate;
    if (startDate && endDate && new Date(startDate).getTime() > new Date(endDate).getTime()) {
      throw new Error("Leave start date must be on or before end date");
    }
    if (next.days !== undefined) {
      const days = Number(next.days);
      if (!Number.isFinite(days) || days <= 0) {
        throw new Error("Leave days must be positive");
      }
    }
    const [row] = await db
      .update(leaveRequests)
      .set({ ...next, updatedAt: new Date() })
      .where(eq(leaveRequests.id, id))
      .returning();
    if (!row) throw new Error("Leave request not found");
    return row;
  }

  async deleteLeaveRequest(id: number): Promise<boolean> {
    const result = await db.delete(leaveRequests).where(eq(leaveRequests.id, id)).returning({ id: leaveRequests.id });
    return result.length > 0;
  }

  async approveLeaveRequest(id: number, approvedBy: number): Promise<LeaveRequest> {
    const [existing] = await db.select().from(leaveRequests).where(eq(leaveRequests.id, id));
    if (!existing) throw new Error("Leave request not found");
    if (existing.status !== "pending") {
      throw new Error("Only pending leave requests can be approved");
    }
    const now = new Date();
    const [row] = await db
      .update(leaveRequests)
      .set({
        status: "approved",
        approvedBy,
        updatedAt: now,
      })
      .where(eq(leaveRequests.id, id))
      .returning();
    if (!row) throw new Error("Leave request not found");
    if (existing.startDate && new Date(existing.startDate) <= now) {
      await db
        .update(employees)
        .set({ status: "on_leave", updatedAt: now })
        .where(eq(employees.id, existing.employeeId));
    }
    return row;
  }

  async rejectLeaveRequest(id: number, approvedBy: number, notes?: string): Promise<LeaveRequest> {
    const [existing] = await db.select().from(leaveRequests).where(eq(leaveRequests.id, id));
    if (!existing) throw new Error("Leave request not found");
    if (existing.status !== "pending") {
      throw new Error("Only pending leave requests can be rejected");
    }
    const [row] = await db
      .update(leaveRequests)
      .set({
        status: "rejected",
        approvedBy,
        notes: notes ?? existing.notes,
        updatedAt: new Date(),
      })
      .where(eq(leaveRequests.id, id))
      .returning();
    if (!row) throw new Error("Leave request not found");
    return row;
  }

